-- =====================================================================
-- Vambora — BASE DEMONSTRATIVA "VB150" (Araçatuba) — IMPORTAÇÃO
-- ---------------------------------------------------------------------
-- GERADO por scripts/demo-aracatuba/build-sql.mjs (não editar à mão).
-- 150 motoristas, 150 veículos, 300 rotas
-- (150 ida + 150 volta), 2045 paradas, 4072 passageiros.
--
-- Pontos de embarque: locais PÚBLICOS reais do OpenStreetMap (ponto de
-- ônibus, praça, farmácia, UBS, terminal...), com osm_id no rótulo como
-- prova. NUNCA sobre a coordenada da escola; não são residências reais.
-- Escolas: apenas REFERENCIADAS por id (não recadastradas).
--
-- Identificadores ESTÁVEIS com prefixo de pacote 'b150d0' (uuid), o que
-- permite remoção precisa (ver remover-demo-150-aracatuba.sql) sem tocar
-- em dados reais nem em demonstrações anteriores (ids aleatórios).
-- Idempotente (upsert por id + limpeza dos filhos do próprio pacote).
-- Transacional (begin/commit). NÃO cria usuários no Supabase Auth: o dono
-- placeholder é um profile existente (admin, senão o primeiro profile).
-- =====================================================================
begin;

-- Cidade garantida (idempotente).

-- Guarda: é preciso ao menos 1 profile para ser o dono placeholder de
-- veículos/rotas (owner_id NOT NULL → profiles → auth.users). Erro claro
-- em vez de violação de FK.
do $$ begin
  if (select count(*) from public.profiles) = 0 then
    raise exception 'Nenhum profile encontrado para dono placeholder. Crie um usuário/admin antes de importar a demo.';
  end if;
end $$;

-- MOTORISTAS (150) — is_demo=true, dono placeholder (owner_id null).
on conflict (id) do update set slug=excluded.slug,name=excluded.name,description=excluded.description,city_id=excluded.city_id,neighborhoods=excluded.neighborhoods,turnos=excluded.turnos,capacity_total=excluded.capacity_total,seats_available=excluded.seats_available,feature_ac=excluded.feature_ac,feature_monitor=excluded.feature_monitor,feature_seatbelt=excluded.feature_seatbelt,feature_accessible=excluded.feature_accessible,price_type=excluded.price_type,price_month=excluded.price_month,price_daily=excluded.price_daily,boarding_time=excluded.boarding_time,is_demo=true,is_published=excluded.is_published,is_suspended=excluded.is_suspended;

-- VEÍCULOS (150) — is_demo=true, dono = admin (ou 1º profile).
with o as (select coalesce((select user_id from public.user_roles where role='admin' limit 1),(select id from public.profiles limit 1)) as oid)
select v.id,o.oid,v.model,v.year,v.plate,v.seats,v.ac,v.acc,v.belt,'{}'::text[],true from o cross join (values
