('b150d003-0000-0000-0000-00000000012b'::uuid,'b150d002-0000-0000-0000-000000000096'::uuid,'Transporte Escolar Demo 150 — Colégio Alameda — noite — ida','ida','noite',false,false,0,1120,1060),
('b150d003-0000-0000-0000-00000000012c'::uuid,'b150d002-0000-0000-0000-000000000096'::uuid,'Transporte Escolar Demo 150 — Colégio Alameda — noite — volta','volta','noite',false,false,0,1377,1317)
) as r(id,vehicle_id,name,direction,turno,monitor,mol,reserved,ldm,elm)
on conflict (id) do update set owner_id=excluded.owner_id,vehicle_id=excluded.vehicle_id,city_id=excluded.city_id,name=excluded.name,direction=excluded.direction,turno=excluded.turno,days=excluded.days,monitor=excluded.monitor,monitor_ocupa_lugar=excluded.monitor_ocupa_lugar,reserved_seats=excluded.reserved_seats,last_dropoff_min=excluded.last_dropoff_min,early_leave_limit_min=excluded.early_leave_limit_min,status='concluida',is_demo=true,is_published=true;

-- Limpeza idempotente: remove paradas/passageiros ANTIGOS deste pacote
-- (prefixo b150d0) antes de reinserir o estado atual. Só toca no pacote.
delete from public.route_passengers where route_id::text like 'b150d0%';
delete from public.route_stops      where route_id::text like 'b150d0%';

-- PARADAS (2045).
on conflict (id) do update set route_id=excluded.route_id,ordem=excluded.ordem,type=excluded.type,label=excluded.label,lat=excluded.lat,lng=excluded.lng,confirmed=excluded.confirmed,destination_id=excluded.destination_id,leg_time_min=excluded.leg_time_min,habitual_arrival_min=excluded.habitual_arrival_min;

-- PASSAGEIROS (4072) — identificadores anônimos (nenhum nome real).
on conflict (id) do update set route_id=excluded.route_id,identificacao=excluded.identificacao,board_stop_id=excluded.board_stop_id,alight_stop_id=excluded.alight_stop_id,destination_id=excluded.destination_id,horario_habitual_min=excluded.horario_habitual_min,atendimento_min=excluded.atendimento_min,atendimento_origem=excluded.atendimento_origem;

-- VÍNCULO MOTORISTA↔ESCOLA (179).
on conflict (driver_id,destination_id) do nothing;

commit;

